// ScrollToTop.jsx
import { useEffect } from "react";
import { useLocation } from "react-router-dom";

export default function ScrollToTop() {
  const location = useLocation();

  useEffect(() => {
    // Wait a bit so layout finishes
    setTimeout(() => {
      window.scrollTo(0, 0);
      console.log("✅ Scroll reset on", location.pathname);
    }, 100); // ← This delay helps if layout is async
  }, [location.pathname]);

  return null;
}
